import { Hono } from "hono";
import { zValidator } from "@hono/zod-validator";
import { z } from "zod";
import { eq } from "drizzle-orm";
import { db } from "../../database";
import { users } from "../../database/schema/users"; // verify export name
import {
  requireAuth,
  requireAdmin,
  type AuthVariables,
} from "../../middleware/auth";

const roleAssignmentSchema = z.object({
  role: z.enum(["customer", "content-manager"]),
});

export const adminCustomersApp = new Hono<{ Variables: AuthVariables }>();

adminCustomersApp.use("*", requireAuth, requireAdmin);

adminCustomersApp.get("/", async (c) => {
  const list = await db
    .select({
      id: users.id,
      name: users.name,
      email: users.email,
      role: users.role,
      createdAt: users.createdAt,
    })
    .from(users)
    .orderBy(users.createdAt);
  return c.json({ customers: list });
});

adminCustomersApp.put(
  "/:id/role",
  zValidator("json", roleAssignmentSchema),
  async (c) => {
    const id = c.req.param("id");
    const { role } = c.req.valid("json");

    const [target] = await db.select().from(users).where(eq(users.id, id));
    if (!target) {
      return c.json({ error: "NotFound", message: "User not found" }, 404);
    }
    if (target.role === "admin" || target.role === "super-admin") {
      return c.json(
        { error: "Forbidden", message: "Cannot change role of admin accounts" },
        403
      );
    }

    await db.update(users).set({ role }).where(eq(users.id, id));
    return c.json({ success: true, id, role });
  }
);

