import { describe, it, expect } from 'vitest'
import sharp from 'sharp'
import { MAT_CANVAS, MAT_ART_INSET } from '@chobii/shared'
import { matToSquare } from '../../src/lib/image-processing'

/** Solid-colour source so trim() can find the art against the mat. */
const src = (w: number, h: number) =>
  sharp({ create: { width: w, height: h, channels: 3, background: { r: 10, g: 20, b: 30 } } })
    .png().toBuffer()

const RATIOS: Array<[string, number, number]> = [
  ['square 1:1', 1200, 1200],
  ['portrait 2:3', 1000, 1500],
  ['landscape 3:2', 1500, 1000],
  ['panoramic 16:9', 1600, 900],
]

describe('matToSquare', () => {
  it.each(RATIOS)('%s -> 1500x1500', async (_label, w, h) => {
    const out = await matToSquare(await src(w, h))
    const m = await sharp(out).metadata()
    expect(m.width).toBe(MAT_CANVAS)
    expect(m.height).toBe(MAT_CANVAS)
    expect(m.format).toBe('webp')
  })

  it.each(RATIOS)('%s insets art to 88% of the longest side', async (_label, w, h) => {
    const out = await matToSquare(await src(w, h))
    // trim the flat mat away; what remains is the art box
    const { info } = await sharp(out).trim().toBuffer({ resolveWithObject: true })
    const longest = Math.max(info.width, info.height)
    expect(longest).toBeCloseTo(MAT_CANVAS * MAT_ART_INSET, -1) // 1320 +/- ~2px
  })

  it.each(RATIOS)('%s centres the art', async (_label, w, h) => {
    const out = await matToSquare(await src(w, h))
    const { info } = await sharp(out).trim().toBuffer({ resolveWithObject: true })
    const leftGap = (MAT_CANVAS - info.width) / 2
    const topGap = (MAT_CANVAS - info.height) / 2
    expect(leftGap).toBeGreaterThanOrEqual(0)
    expect(topGap).toBeGreaterThanOrEqual(0)
    // centred: gaps on both axes are symmetric by construction
    expect(MAT_CANVAS - info.width - leftGap).toBeCloseTo(leftGap, 0)
    expect(MAT_CANVAS - info.height - topGap).toBeCloseTo(topGap, 0)
  })

  it('never upscales a small source', async () => {
    const out = await matToSquare(await src(600, 600))
    const { info } = await sharp(out).trim().toBuffer({ resolveWithObject: true })
    expect(Math.max(info.width, info.height)).toBeLessThanOrEqual(602)
  })

  it('is idempotent in output size for an already-square 1500 source', async () => {
    const out = await matToSquare(await src(1500, 1500))
    const m = await sharp(out).metadata()
    expect(m.width).toBe(MAT_CANVAS)
    expect(m.height).toBe(MAT_CANVAS)
  })
})

import { MAT_COLOR, MAT_CANVAS, MAT_ART_INSET } from '@chobii/shared'

/**
 * Composite artwork of ANY aspect ratio onto an opaque square mat.
 *
 * Output is always MAT_CANVAS x MAT_CANVAS - this is the invariant the product
 * grid rests on. Art is contained (never cropped) at MAT_ART_INSET of the
 * longest side, so every product shows a visible mat and square art does not
 * bleed to the card edge.
 *
 * Small sources are NOT upscaled: they sit smaller on the mat rather than being
 * interpolated. Fake resolution is worse than a wider mat.
 */
export async function matToSquare(input: Buffer): Promise<Buffer> {
  const inner = Math.round(MAT_CANVAS * MAT_ART_INSET)

  const art = await sharp(input)
    .resize(inner, inner, { fit: 'inside', withoutEnlargement: true })
    .toBuffer()

  return sharp({
    create: {
      width: MAT_CANVAS,
      height: MAT_CANVAS,
      channels: 3,
      background: MAT_COLOR,
    },
  })
    .composite([{ input: art, gravity: 'centre' }])
    .webp({ quality: 88 })
    .toBuffer()
}

import { describe, it, expect } from 'vitest'
import sharp from 'sharp'
import { MAT_CANVAS } from '@chobii/shared'
import { cropToSquare, centredSquareCrop } from '../../src/lib/image-processing'

/** Left half red, right half blue - lets us prove WHICH region was kept. */
async function halves(w: number, h: number) {
  const left = { create: { width: w / 2, height: h, channels: 3, background: { r: 255, g: 0, b: 0 } } }
  const right = { create: { width: w / 2, height: h, channels: 3, background: { r: 0, g: 0, b: 255 } } }
  return sharp({ create: { width: w, height: h, channels: 3, background: { r: 0, g: 0, b: 0 } } })
    .composite([
      { input: await sharp(left).png().toBuffer(), left: 0, top: 0 },
      { input: await sharp(right).png().toBuffer(), left: w / 2, top: 0 },
    ]).png().toBuffer()
}

const centrePixel = async (buf: Buffer) => {
  const { data } = await sharp(buf).resize(1, 1, { fit: 'fill' }).raw().toBuffer({ resolveWithObject: true })
  return { r: data[0], g: data[1], b: data[2] }
}

describe('cropToSquare', () => {
  it('outputs MAT_CANVAS x MAT_CANVAS webp', async () => {
    const out = await cropToSquare(await halves(1600, 900), { x: 0, y: 0, w: 0.5, h: 1 })
    const m = await sharp(out).metadata()
    expect(m.width).toBe(MAT_CANVAS)
    expect(m.height).toBe(MAT_CANVAS)
    expect(m.format).toBe('webp')
  })

  it('honours the chosen window - left half yields red', async () => {
    const out = await cropToSquare(await halves(1600, 900), { x: 0, y: 0, w: 0.4, h: 1 })
    const px = await centrePixel(out)
    expect(px.r).toBeGreaterThan(200)
    expect(px.b).toBeLessThan(60)
  })

  it('honours the chosen window - right half yields blue', async () => {
    const out = await cropToSquare(await halves(1600, 900), { x: 0.6, y: 0, w: 0.4, h: 1 })
    const px = await centrePixel(out)
    expect(px.b).toBeGreaterThan(200)
    expect(px.r).toBeLessThan(60)
  })

  it('clamps a rect that overflows the source', async () => {
    const out = await cropToSquare(await halves(1600, 900), { x: 0.9, y: 0.9, w: 0.5, h: 0.5 })
    const m = await sharp(out).metadata()
    expect(m.width).toBe(MAT_CANVAS)
  })

  it('clamps a zero-area rect instead of throwing', async () => {
    const out = await cropToSquare(await halves(1600, 900), { x: 0.5, y: 0.5, w: 0, h: 0 })
    const m = await sharp(out).metadata()
    expect(m.width).toBe(MAT_CANVAS)
  })

  it('defaults to the largest centred square when no crop is given', async () => {
    const out = await cropToSquare(await halves(1600, 900))
    const m = await sharp(out).metadata()
    expect(m.width).toBe(MAT_CANVAS)
    expect(m.height).toBe(MAT_CANVAS)
  })
})

describe('centredSquareCrop', () => {
  it('takes full height and a centred slice of a landscape source', () => {
    expect(centredSquareCrop(1600, 900)).toEqual({ x: (1600 - 900) / 2 / 1600, y: 0, w: 900 / 1600, h: 1 })
  })
  it('takes full width and a centred slice of a portrait source', () => {
    expect(centredSquareCrop(900, 1600)).toEqual({ x: 0, y: (1600 - 900) / 2 / 1600, w: 1, h: 900 / 1600 })
  })
  it('is the whole frame for a square source', () => {
    expect(centredSquareCrop(1000, 1000)).toEqual({ x: 0, y: 0, w: 1, h: 1 })
  })
})

import type { ImageCrop } from '@chobii/shared'

/** The largest centred square of a source, as a normalised rect. */
export function centredSquareCrop(width: number, height: number): ImageCrop {
  const side = Math.min(width, height)
  return {
    x: (width - side) / 2 / width,
    y: (height - side) / 2 / height,
    w: side / width,
    h: side / height,
  }
}

const clamp01 = (n: number) => Math.min(1, Math.max(0, Number.isFinite(n) ? n : 0))

/**
 * Crop a photograph to a square using a HUMAN-CHOSEN window, then resize to the
 * canonical canvas. No mat: photographs fill the frame edge-to-edge.
 *
 * The rect is normalised 0..1 against the original so it survives re-encoding.
 * Defends against out-of-range, zero-area and overflowing rects from the client;
 * falls back to the largest centred square.
 */
export async function cropToSquare(input: Buffer, crop?: ImageCrop): Promise<Buffer> {
  const meta = await sharp(input).metadata()
  const sw = meta.width ?? MAT_CANVAS
  const sh = meta.height ?? MAT_CANVAS

  const rect = crop ?? centredSquareCrop(sw, sh)

  let left = Math.round(clamp01(rect.x) * sw)
  let top = Math.round(clamp01(rect.y) * sh)
  let width = Math.round(clamp01(rect.w) * sw)
  let height = Math.round(clamp01(rect.h) * sh)

  // keep the window inside the source and non-degenerate
  width = Math.max(1, Math.min(width, sw - left))
  height = Math.max(1, Math.min(height, sh - top))
  left = Math.min(left, sw - width)
  top = Math.min(top, sh - height)

  return sharp(input)
    .extract({ left, top, width, height })
    .resize(MAT_CANVAS, MAT_CANVAS, { fit: 'fill' })
    .webp({ quality: 88 })
    .toBuffer()
}

