import { randomUUID } from 'node:crypto'
import {
  MAT_CANVAS,
  type ImageCrop,
  type ProductImage,
  type ProductImageType,
} from '@chobii/shared'
import { matToSquare, cropToSquare } from './image-processing'
import { uploadOptimizedImage, uploadFile, StoragePaths } from './storage'

export interface BuildProductMediaInput {
  type: ProductImageType
  altText: string
  /** Ignored for type:'main', which is matted and never cropped. */
  crop?: ImageCrop
  sortOrder?: number
}

/**
 * Turn one uploaded file into one ProductImage satisfying the square contract.
 *
 * Deliberately NOT folded into processImage(): that function also serves avatars
 * and AI generations, where forcing a square would be wrong.
 */
export async function buildProductMedia(
  input: Buffer,
  filename: string,
  contentType: string,
  opts: BuildProductMediaInput,
): Promise<ProductImage> {
  // 1. square it - matted for artwork, human-cropped for photographs
  const squared =
    opts.type === 'main'
      ? await matToSquare(input)
      : await cropToSquare(input, opts.crop)

  // 2. existing variant ladder + upload (unchanged)
  const uploaded = await uploadOptimizedImage(squared, `${filename}.webp`, 'image/webp', {
    prefix: StoragePaths.PRODUCTS,
  })

  // 3. retain the untouched source so the crop stays revisable
  const original = await uploadFile(input, filename, contentType, {
    prefix: `${StoragePaths.PRODUCTS}originals/`,
  })

  return {
    id: randomUUID(),
    url: uploaded.url,
    altText: opts.altText,
    type: opts.type,
    sortOrder: opts.sortOrder ?? 0,
    width: MAT_CANVAS,
    height: MAT_CANVAS,
    variants: uploaded.variants,
    ...(opts.type === 'main' ? {} : opts.crop ? { crop: opts.crop } : {}),
    originalKey: original.key,
  }
}

// near the other imports
import { z } from 'zod'
import { buildProductMedia } from '../../lib/product-media'

const uploadImageFieldsSchema = z.object({
  type: z.enum(['main', 'detail', 'texture', 'room-mockup', 'frame-preview', '360-view']).default('main'),
  altText: z.string().max(300).default(''),
  sortOrder: z.coerce.number().int().min(0).default(0),
  crop: z
    .string()
    .optional()
    .transform((s, ctx) => {
      if (!s) return undefined
      try {
        const p = JSON.parse(s)
        return z.object({ x: z.number(), y: z.number(), w: z.number(), h: z.number() }).parse(p)
      } catch {
        ctx.addIssue({ code: z.ZodIssueCode.custom, message: 'crop must be JSON {x,y,w,h}' })
        return z.NEVER
      }
    }),
})

// inside the POST /upload-image handler, replacing the uploadOptimizedImage call.
// KEEP the existing PRODUCT_IMAGE_TYPES and MAX_PRODUCT_IMAGE_MB guards above this.
const form = await c.req.formData()
const parsed = uploadImageFieldsSchema.safeParse({
  type: form.get('type') ?? undefined,
  altText: form.get('altText') ?? undefined,
  sortOrder: form.get('sortOrder') ?? undefined,
  crop: form.get('crop') ?? undefined,
})
if (!parsed.success) {
  return c.json({ error: 'Invalid upload fields', details: parsed.error.flatten() }, 400)
}

const buffer = Buffer.from(await file.arrayBuffer())
const image = await buildProductMedia(buffer, file.name, file.type, parsed.data)

return c.json({ success: true, image }, 201)

