/** Single source of truth for card media geometry and motion. */

/** The square invariant, in Tailwind form. Skeleton and card MUST share this. */
export const MEDIA_RATIO = 'aspect-square'

/**
 * Mesonart omits sizes entirely, causing a measured 6.7x over-fetch
 * (1080w into a 160.75px card at 375px). Column counts: 2 / md:3 / xl:4.
 */
export const SIZES_ATTR = '(min-width:1280px) 25vw, (min-width:768px) 33vw, 50vw'

/** --animation-primary: .5s cubic-bezier(.3, 1, .3, 1) */
export const EASE_PRIMARY = 'ease-[cubic-bezier(.3,1,.3,1)]'

/** --animation-fast: .3s cubic-bezier(.7, 0, .3, 1) */
export const EASE_FAST = 'ease-[cubic-bezier(.7,0,.3,1)]'

/** Divide the media box into n-1 zones; slide 0 is the not-hovered state. */
export function zoneFor(clientX: number, el: HTMLElement, n: number): number {
  if (n < 2) return 0
  const { left, width } = el.getBoundingClientRect()
  if (width <= 0) return 1
  const zones = n - 1
  const raw = Math.ceil(((clientX - left) / width) * zones)
  return Math.min(zones, Math.max(1, raw || 1))
}

import { describe, it, expect } from 'vitest'
import { zoneFor } from '~/components/product/productCardTokens'

const el = (left = 0, width = 100) =>
  ({ getBoundingClientRect: () => ({ left, width }) }) as unknown as HTMLElement

describe('zoneFor', () => {
  // measured on mesonart with 4 media, entering fresh at each fraction
  it.each([
    [0.02, 1], [0.10, 1], [0.20, 1],
    [0.35, 2], [0.50, 2], [0.65, 2],
    [0.80, 3], [0.98, 3],
  ])('4 media, x=%s -> slide %i', (frac, expected) => {
    expect(zoneFor(frac * 100, el(), 4)).toBe(expected)
  })

  it.each([[0.2, 1], [0.49, 1], [0.51, 2], [0.9, 2]])('3 media, x=%s -> slide %i', (frac, expected) => {
    expect(zoneFor(frac * 100, el(), 3)).toBe(expected)
  })

  it('2 media always selects slide 1', () => {
    for (const f of [0.01, 0.5, 0.99]) expect(zoneFor(f * 100, el(), 2)).toBe(1)
  })

  it('generalises past mesonart, which hardcodes 2|3|4 and no-ops for 5+', () => {
    expect(zoneFor(0.1 * 100, el(), 6)).toBe(1)
    expect(zoneFor(0.99 * 100, el(), 6)).toBe(5)
  })

  it('returns 0 for a single image (no hover)', () => {
    expect(zoneFor(50, el(), 1)).toBe(0)
  })

  it('respects a non-zero element offset', () => {
    expect(zoneFor(500 + 10, el(500, 100), 4)).toBe(1)
    expect(zoneFor(500 + 90, el(500, 100), 4)).toBe(3)
  })

  it('clamps a cursor outside the box', () => {
    expect(zoneFor(-50, el(), 4)).toBe(1)
    expect(zoneFor(9999, el(), 4)).toBe(3)
  })
})

