import { test, expect, type Page } from '@playwright/test'

const WIDTHS = [
  { w: 1440, h: 900, cols: 4 },
  { w: 1024, h: 900, cols: 3 },
  { w: 375, h: 812, cols: 2 },
]

async function cardBoxes(page: Page) {
  return page.$$eval('[data-testid="product-card"]', (els) =>
    els.map((el) => {
      const r = el.getBoundingClientRect()
      const media = el.querySelector('[data-testid="media-box"]')!.getBoundingClientRect()
      return {
        top: Math.round(r.top),
        height: +r.height.toFixed(2),
        mediaW: +media.width.toFixed(2),
        mediaH: +media.height.toFixed(2),
      }
    }),
  )
}

for (const { w, h, cols } of WIDTHS) {
  test.describe(`grid at ${w}px`, () => {
    test.beforeEach(async ({ page }) => {
      await page.setViewportSize({ width: w, height: h })
      await page.goto('/posters', { waitUntil: 'networkidle' })
    })

    test(`renders ${cols} columns`, async ({ page }) => {
      const boxes = await cardBoxes(page)
      const rows = new Map<number, number>()
      boxes.forEach((b) => rows.set(b.top, (rows.get(b.top) ?? 0) + 1))
      expect(Math.max(...rows.values())).toBe(cols)
    })

    test('every card in a row has an identical height', async ({ page }) => {
      const boxes = await cardBoxes(page)
      expect(boxes.length).toBeGreaterThan(0)
      const rows = new Map<number, Set<number>>()
      boxes.forEach((b) => {
        if (!rows.has(b.top)) rows.set(b.top, new Set())
        rows.get(b.top)!.add(b.height)
      })
      for (const [top, heights] of rows) {
        expect(heights.size, `row at y=${top} has heights ${[...heights].join(', ')}`).toBe(1)
      }
    })

    test('every media box is square', async ({ page }) => {
      for (const b of await cardBoxes(page)) {
        expect(Math.abs(b.mediaW - b.mediaH)).toBeLessThanOrEqual(1)
      }
    })
  })
}

