function hslToRgb(h: number, s: number, l: number) {
  const sn = s / 100, ln = l / 100
  const k = (n: number) => (n + h / 30) % 12
  const a = sn * Math.min(ln, 1 - ln)
  const f = (n: number) => ln - a * Math.max(-1, Math.min(k(n) - 3, Math.min(9 - k(n), 1)))
  return { r: Math.round(255 * f(0)), g: Math.round(255 * f(8)), b: Math.round(255 * f(4)) }
}

function token(name: string, source = css) {
  const m = source.match(new RegExp(`${name}:\\s*([\\d.]+)\\s+([\\d.]+)%\\s+([\\d.]+)%`))
  expect(m, `${name} not found`).not.toBeNull()
  return hslToRgb(Number(m![1]), Number(m![2]), Number(m![3]))
}

function near(got: {r:number;g:number;b:number}, r: number, g: number, b: number, tol = 2) {
  expect(Math.abs(got.r - r)).toBeLessThanOrEqual(tol)
  expect(Math.abs(got.g - g)).toBeLessThanOrEqual(tol)
  expect(Math.abs(got.b - b)).toBeLessThanOrEqual(tol)
}

