import { cva, type VariantProps } from 'class-variance-authority'
import { forwardRef } from 'react'
import { cn } from '~/lib/utils'

/**
 * The storefront button, measured from mesonart.com.
 *
 * Near-black pill, 2px border, fluid type. There was no Button component
 * before this one, which is why orange spread across ~54 files by hand.
 * New buttons go through here.
 */
export const buttonVariants = cva(
  'inline-flex items-center justify-center gap-2 whitespace-nowrap font-medium text-button transition-colors duration-300 ' +
    'disabled:pointer-events-none disabled:opacity-50 ' +
    'focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2',
  {
    variants: {
      variant: {
        solid:
          'rounded-pill border-[length:var(--border-button)] border-primary bg-primary text-primary-foreground hover:bg-primary/85 hover:border-primary/85',
        outline:
          'rounded-pill border-[length:var(--border-button)] border-primary bg-transparent text-primary hover:bg-primary hover:text-primary-foreground',
        ghost:
          'rounded-pill border-[length:var(--border-button)] border-transparent text-foreground hover:bg-accent',
        link: 'text-foreground underline-offset-4 hover:underline',
      },
      size: {
        sm: 'h-9 px-5',
        md: 'h-11 px-7',
        lg: 'h-12 px-8',
        icon: 'h-10 w-10 rounded-full p-0',
      },
    },
    defaultVariants: { variant: 'solid', size: 'md' },
  }
)

export interface ButtonProps
  extends React.ButtonHTMLAttributes<HTMLButtonElement>,
    VariantProps<typeof buttonVariants> {}

export const Button = forwardRef<HTMLButtonElement, ButtonProps>(
  ({ className, variant, size, type = 'button', ...props }, ref) => (
    <button
      ref={ref}
      type={type}
      className={cn(buttonVariants({ variant, size }), className)}
      {...props}
    />
  )
)
Button.displayName = 'Button'

export default Button

