import { cn } from '~/lib/utils'

export interface DisplayHeadingProps
  extends React.HTMLAttributes<HTMLHeadingElement> {
  as?: 'h1' | 'h2'
  children: string
}

/**
 * mesonart splits display headings into per-word spans and reveals them in
 * sequence. The whitespace between words is preserved so the accessible name
 * and copy-paste stay intact.
 */
export function DisplayHeading({ as: Tag = 'h1', className, children, ...props }: DisplayHeadingProps) {
  const words = children.split(/(\s+)/)
  return (
    <Tag className={cn('font-heading font-light tracking-tight', className)} {...props}>
      {words.map((word, i) =>
        /^\s+$/.test(word) ? (
          word
        ) : (
          <span
            key={i}
            data-word
            className="inline-block animate-word-reveal"
            style={{ animationDelay: `${(i / 2) * 60}ms` }}
          >
            {word}
          </span>
        )
      )}
    </Tag>
  )
}

