import { describe, it, expect } from 'vitest'
import { readFileSync, readdirSync, statSync } from 'node:fs'
import { join, relative } from 'node:path'

/**
 * Storefront design-token compliance.
 *
 * The mesonart palette lives in tokens; the whole point of the parity work was
 * that components stopped ignoring them. Nothing in the type system notices a
 * new `font-bold`, so it is noticed here.
 *
 * Each exemption below needs a reason in writing.
 */
const APP = join(process.cwd(), 'app')

const EXEMPT = [
  // Internal tool, not customer-facing. Deliberately keeps its own look.
  'components/admin/',
  'routes/admin',
  // Our differentiator surface, explicitly retained on the brand scale.
  'components/ai-generator/',
]

const FORBIDDEN: Array<[RegExp, string]> = [
  [/\bfont-(bold|extrabold|black)\b/, 'weight 700+ is never loaded — renders faux-bold. Use font-medium or the base heading style.'],
  [/\b(fill|text)-yellow-400\b/, 'use the --rating token: fill-rating / text-rating.'],
  [/\b(bg|from|to)-brand-/, 'the brand scale is admin/AI-only. Use primary.'],
  [/\bblur-3xl\b/, 'marketing blob idiom — stripped for the monochrome system.'],
]

function walk(dir: string, out: string[] = []) {
  for (const entry of readdirSync(dir)) {
    const full = join(dir, entry)
    if (statSync(full).isDirectory()) walk(full, out)
    else if (full.endsWith('.tsx')) out.push(full)
  }
  return out
}

const files = walk(APP)
  .map((f) => relative(APP, f))
  .filter((f) => !EXEMPT.some((e) => f.includes(e)))

describe('storefront token compliance', () => {
  it('finds storefront files to check', () => {
    expect(files.length).toBeGreaterThan(20)
  })

  for (const [pattern, why] of FORBIDDEN) {
    it(`no ${pattern.source} — ${why}`, () => {
      const offenders = files.filter((f) =>
        pattern.test(readFileSync(join(APP, f), 'utf8'))
      )
      expect(offenders, `${why}\nOffending files:\n  ${offenders.join('\n  ')}`).toEqual([])
    })
  }
})

