/**
 * GET /api/products/collections - Discover chips (analysis §1.3.2)
 *
 * Labels come from STYLE_OPTIONS in @chobii/shared, never from a literal
 * here: features #395-#399 removed the last parallel vocabulary and this
 * would reintroduce it.
 *
 * Registered BEFORE `/:slug`, same as `/facets`.
 */
productsApp.get("/collections", async (c) => {
  const cacheKey = `${CacheKeys.PRODUCT}collections:v1`;
  const cached = await getCached<Record<string, unknown>>(cacheKey);
  if (cached) return c.json({ ...cached, fromCache: true });

  try {
    // Counts per style. `styles` is text[], so unnest before grouping.
    const counts = await db
      .select({
        value: sql<string>`unnest(${products.styles})`,
        count: sql<number>`count(*)::int`,
      })
      .from(products)
      .where(eq(products.status, "active"))
      .groupBy(sql`1`);

    // One representative product per style: highest featuredOrder, else newest.
    const representatives = await db.execute(sql`
      select distinct on (style) style, images
      from (
        select unnest(styles) as style, images, featured_order, created_at
        from products where status = 'active'
      ) t
      order by style, featured_order asc nulls last, created_at desc
    `);

    const imageByStyle = new Map<string, string | null>();
    for (const row of representatives.rows as any[]) {
      const first = Array.isArray(row.images) ? row.images[0] : null;
      imageByStyle.set(row.style, first?.url ?? null);
    }

    const countByStyle = new Map(counts.map((r) => [r.value, r.count]));

    const collections = STYLE_OPTIONS.map((option) => ({
      id: option.id,
      label: option.label,
      count: countByStyle.get(option.id) ?? 0,
      image: imageByStyle.get(option.id) ?? null,
    })).filter((collection) => collection.count > 0);

    const result = { collections };
    await setCached(cacheKey, result, CACHE_TTL_FACETS);
    return c.json(result);
  } catch (error) {
    console.error("Error fetching collections:", error);
    return c.json({ error: "Failed to fetch collections" }, 500);
  }
});

