/**
 * GET /api/reviews/stats - catalogue-wide aggregate.
 *
 * Feeds the collection-grid promo tile. averageRating is NULL when nothing
 * is approved: a synthetic 0.0 reads as "rated badly" rather than "not yet
 * rated", which is the fabricated-social-proof case the parity analysis
 * rules out. The tile renders nothing on null.
 *
 * Registered BEFORE `/:reviewId` or "stats" is read as a review id.
 */
reviewsApp.get("/stats", async (c) => {
  const cacheKey = `${REVIEW_CACHE_PREFIX}stats:catalogue:v1`;
  const cached = await getCached<{ averageRating: number | null; reviewCount: number }>(cacheKey);
  if (cached) return c.json(cached);

  try {
    const [row] = await db
      .select({
        averageRating: sql<number | null>`round(avg(${reviews.rating})::numeric, 1)`,
        reviewCount: sql<number>`count(*)::int`,
      })
      .from(reviews)
      .where(eq(reviews.status, "approved" as ReviewStatus));

    const payload = {
      averageRating: row?.reviewCount ? Number(row.averageRating) : null,
      reviewCount: row?.reviewCount ?? 0,
    };

    await setCached(cacheKey, payload, CACHE_TTL_REVIEWS);
    return c.json(payload);
  } catch (error) {
    console.error("Error fetching catalogue review stats:", error);
    return c.json({ error: "Failed to fetch review stats" }, 500);
  }
});

