/**
 * A grid cell carrying real social proof (analysis §1.3.6).
 *
 * mesonart's reads "Rated 4.9/5 by 9,000+ Users". Ours says what is true or
 * says nothing: below MIN_REVIEWS the component returns null rather than
 * round a thin sample up into a marketing number.
 */
const MIN_REVIEWS = 10

export function PromoTile({
  averageRating,
  reviewCount,
}: {
  averageRating: number | null
  reviewCount: number
}) {
  if (averageRating === null || reviewCount < MIN_REVIEWS) return null
  // <li> - the grid is a <ul> and a bare <div> breaks list semantics.
  // Beige band tone, rating token for the stars, Button pill to /reviews.
}

export interface ProductGridProps {
  products: ProductCardData[]
  /**
   * One promo cell, spliced in at `index`. Exactly ONE cell wide - which is
