interface WishlistStore {
  /** Product ids the user has saved. */
  ids: string[]
  /** Whether `load()` has completed at least once. */
  isLoaded: boolean
  /** A toggle request is in flight. */
  isPending: boolean
  /**
   * `null` until the root route reports the session. Leaf effects run before
   * the root's, so "unknown" has to mean "do nothing" — otherwise a guest
   * spends one 401 per mounting heart before the answer arrives.
   */
  isAuthenticated: boolean | null
  /** Shared by concurrent callers: N cards mounting produce one request. */
  inFlight: Promise<void> | null

  setAuthenticated: (value: boolean) => void
  load: () => Promise<void>
  toggle: (productId: string) => Promise<void>
}

export const useWishlistStore = create<WishlistStore>()((set, get) => ({
  ids: [],
  isLoaded: false,
  isPending: false,
  isAuthenticated: null,
  inFlight: null,

  setAuthenticated(value: boolean) {
    if (get().isAuthenticated === value) return
    set({ isAuthenticated: value })

    if (value) {
      void get().load()
      return
    }

    // A guest has nothing on the server. Mark loaded so the hearts stop
    // waiting and every one of them renders empty.
    set({ ids: [], isLoaded: true })
  },

  async load() {
    // Session unknown or signed out: the request would only ever be a 401.
    if (get().isAuthenticated !== true) return
    if (get().isLoaded) return

    const existing = get().inFlight
    if (existing) return existing

    const request = (async () => {
      try {
        const { items } = await wishlistApi.list()
        set({ ids: items.map((item) => item.id), isLoaded: true })
      } catch {
        // A session can still expire between the root route and here; treat it
        // the way a guest is treated rather than leaving the hearts pending.
        set({ ids: [], isLoaded: true })
      } finally {
        set({ inFlight: null })
      }
    })()

    // The body above runs synchronously up to the first await, so this is set
    // before `load()` returns and the next caller in the same tick sees it.
    set({ inFlight: request })
    return request
  },

  // ...toggle unchanged
}))

