    expect(deadline).toEqual(existing)
    expect(shouldSetCookie).toBe(false)
  })

  it('re-mints once the previous window has run out', () => {
    const expired = new Date(NOW.getTime() - 1000)
    const { shouldSetCookie } = resolveCountdownDeadline(promo, expired, NOW, () => 0)
    expect(shouldSetCookie).toBe(true)
  })

  it('clamps to the real end — never shows more time than remains', () => {
    const ending = { ...promo, endsAt: new Date(NOW.getTime() + 30 * 60_000) }
    const { deadline } = resolveCountdownDeadline(ending, null, NOW, () => 0)
    expect(deadline).toEqual(ending.endsAt)
  })

  it("uses endsAt directly in 'real' mode and ignores the cookie", () => {
    const real = {
      ...promo,
      countdownMode: 'real' as const,
      endsAt: new Date('2026-08-31T00:00:00.000Z'),
    }
    const cookie = new Date(NOW.getTime() + 60_000)
    const { deadline, shouldSetCookie } = resolveCountdownDeadline(real, cookie, NOW, () => 0)
    expect(deadline).toEqual(real.endsAt)
    expect(shouldSetCookie).toBe(false)
  })
})

/**
 * The countdown a visitor sees.
 *
 * In 'rolling' mode the deadline is per-visitor and re-mints when it runs
 * out — the urgency device described in the design doc §6, including the
 * legal note there. It is a configured behaviour, not a hardcoded one:
 * countdownMode='real' makes the timer truthful in a single admin edit.
 *
 * The displayed deadline is always min(minted, endsAt), so it never claims
 * more time than actually remains, and drops below the usual window when the
 * sale genuinely is ending.
 *
 * `endsAt` itself is never serialized — only the resolved deadline.
 */

export type CountdownConfig = {
  id: string
  countdownMode: 'real' | 'rolling'
  rollingWindowMinutes: number
  rollingJitterMinutes: number
  endsAt: Date | null
}

export const countdownCookieName = (promotionId: string) => `promo_deadline_${promotionId}`

export function resolveCountdownDeadline(
  promotion: CountdownConfig,
  cookieDeadline: Date | null,
  now: Date = new Date(),
  random: () => number = Math.random
): { deadline: Date; shouldSetCookie: boolean } {
  if (promotion.countdownMode === 'real') {
    return { deadline: promotion.endsAt ?? now, shouldSetCookie: false }
  }

  const live = cookieDeadline && cookieDeadline > now
  const minted = live
    ? cookieDeadline
    : new Date(
        now.getTime() +
          (promotion.rollingWindowMinutes - random() * promotion.rollingJitterMinutes) * 60_000
      )

  const deadline =
    promotion.endsAt && promotion.endsAt < minted ? promotion.endsAt : minted

  return { deadline, shouldSetCookie: !live }
}

