/**
 * Joining the gallery.
 *
 * Idempotent: re-joining does not move galleryJoinedAt or re-stamp consent.
 * The first consent date is the one that has to be producible if the consent
 * is ever questioned.
 */

import { Hono } from 'hono'
import { z } from 'zod'
import { eq } from 'drizzle-orm'
import { db } from '../database'
import { users } from '../database/schema/users'

const joinSourceSchema = z.enum(['banner', 'rail', 'cart', 'registration', 'sale-page'])

const gallery = new Hono()

gallery.post('/join', async (c) => {
  const user = c.get('user')
  if (!user) return c.json({ error: 'Sign in to join the gallery' }, 401)

  const parsed = joinSourceSchema.safeParse((await c.req.json().catch(() => ({}))).source)
  if (!parsed.success) return c.json({ error: 'Unknown join source' }, 400)

  const [existing] = await db
    .select({ galleryMember: users.galleryMember, joinedAt: users.galleryJoinedAt })
    .from(users)
    .where(eq(users.id, user.id))

  if (existing?.galleryMember) {
    return c.json({ galleryMember: true, galleryJoinedAt: existing.joinedAt })
  }

  const now = new Date()
  await db
    .update(users)
    .set({
      galleryMember: true,
      galleryJoinedAt: now,
      marketingConsentAt: now,
      joinSource: parsed.data,
    })
    .where(eq(users.id, user.id))

  return c.json({ galleryMember: true, galleryJoinedAt: now })
})

export default gallery

