import { useSession } from '~/lib/auth-client'

export type JoinSource = 'banner' | 'rail' | 'cart' | 'registration' | 'sale-page'

export function useGalleryMembership() {
  const { data, isPending, refetch } = useSession()
  const isMember = Boolean(data?.user?.galleryMember)

  async function join(source: JoinSource) {
    const response = await fetch('/api/gallery/join', {
      method: 'POST',
      credentials: 'include',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ source }),
    })
    if (!response.ok) return false
    await refetch()
    return true
  }

  return { isMember, isLoading: isPending, join }
}

