export function AllArtMegaMenu({ onNavigate }: { onNavigate?: () => void }) {
  const [isOpen, setIsOpen] = useState(false)
  const rootRef = useRef<HTMLDivElement>(null)

  // Escape and outside-click close it. Hover-open has no keyboard path by
  // decision, but a panel that cannot be dismissed without moving the mouse
  // back through it is a trap.
  useEffect(() => {
    if (!isOpen) return
    const onKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'Escape') setIsOpen(false)
    }
    const onPointerDown = (e: PointerEvent) => {
      if (!rootRef.current?.contains(e.target as Node)) setIsOpen(false)
    }
    document.addEventListener('keydown', onKeyDown)
    document.addEventListener('pointerdown', onPointerDown)
    return () => {
      document.removeEventListener('keydown', onKeyDown)
      document.removeEventListener('pointerdown', onPointerDown)
    }
  }, [isOpen])

  const close = () => {
    setIsOpen(false)
    onNavigate?.()
  }

  return (
    <div
      ref={rootRef}
      onMouseEnter={() => setIsOpen(true)}
      onMouseLeave={() => setIsOpen(false)}
      data-testid="all-art-mega"
      data-open={isOpen}
    >
      {/* The trigger stays a link: click navigates, hover opens. Theirs does
          the same through `data-link` on the <summary>. */}
      <Link
        to="/posters"
