          bar and grid. Pointer-events off so leaving the panel still closes it. */}
      <div
        aria-hidden="true"
        className={cn(
          'pointer-events-none fixed inset-0 top-0 z-30 bg-black/30 transition-opacity duration-500 motion-reduce:transition-none',
          isOpen ? 'opacity-100' : 'invisible opacity-0'
        )}
      />

      {/* The sheet. Grid-rows 0fr/1fr grows it downward on their curve rather
          than sliding it, which is what `padding 0.5s` does on their side. */}
      <div
        className={cn(
          'absolute left-0 top-full z-40 grid w-full overflow-hidden bg-background transition-[grid-template-rows,opacity] duration-500 motion-reduce:transition-none',
          isOpen
            ? 'grid-rows-[1fr] opacity-100'
            : 'invisible grid-rows-[0fr] opacity-0'
        )}
        style={{ transitionTimingFunction: 'cubic-bezier(0.6, 0, 0.4, 1)' }}
      >
        <div className="min-h-0">
          <div className="container-wide grid grid-cols-[4fr_1fr] gap-6 pb-14 pt-3">
            <div className="grid grid-cols-5 gap-6">
              {MEGA_COLUMNS.map((column) => (
                <div key={column.heading}>
                  {column.headingSearch ? (
                    <Link
                      to="/posters"
                      search={column.headingSearch}
                      onClick={close}
                      className="mb-8 flex items-center gap-1 text-base font-medium capitalize tracking-[-0.4px] text-foreground"
                    >
                      {column.heading}
                      <ChevronRight className="h-4 w-4" />
                    </Link>
