  createdAt: timestamp('created_at').defaultNow().notNull(),
}, (table) => ({
  giftCardIdx: index('gift_card_transaction_gift_card_idx').on(table.giftCardId),
  orderIdx: index('gift_card_transaction_order_idx').on(table.orderId),
  /** Refund capping reads this pair; see the per-order cap in §8. */
  cardOrderTypeIdx: index('gift_card_transaction_card_order_type_idx').on(
    table.giftCardId, table.orderId, table.type,
  ),
}))

export const orderGiftCards = pgTable('order_gift_card', {
  orderId: uuid('order_id').notNull().references(() => orders.id, { onDelete: 'cascade' }),
  giftCardId: uuid('gift_card_id').notNull().references(() => giftCards.id, { onDelete: 'restrict' }),
  /** What this card actually paid. Never mutated by a refund. */
  amountPaise: integer('amount_paise').notNull(),
  createdAt: timestamp('created_at').defaultNow().notNull(),
}, (table) => ({
  pk: primaryKey({ columns: [table.orderId, table.giftCardId] }),
}))

export const giftCardsRelations = relations(giftCards, ({ many, one }) => ({
