import { eq, and, sql } from 'drizzle-orm'
import { giftCards, giftCardTransactions, orderGiftCards, giftCardStatus } from '../database/schema/gift-cards'
import { hashGiftCardCode } from '../lib/gift-card-code'

export class GiftCardError extends Error {}

export interface RedeemedCard {
  giftCardId: string
  last4: string
  amountPaise: number
}

/**
 * Debits gift cards towards an order.
 *
 * Takes the caller's transaction: the debit, `orders.giftCardAmount` and the
 * Razorpay order are one unit of work, and a failure creating the payment
 * must give the customer their balance back.
 */
export async function redeemGiftCards(
  tx: any,
  orderId: string,
  codes: string[],
  amountDuePaise: number,
  userId: string,
): Promise<RedeemedCard[]> {
  // Idempotency first. routes/orders.ts:679 returns an existing Razorpay
  // order on a repeat call, so this runs twice for a single checkout.
  const existing = await tx.select().from(orderGiftCards).where(eq(orderGiftCards.orderId, orderId))
  if (existing.length > 0) {
    return existing.map((row: any) => ({
      giftCardId: row.giftCardId,
      last4: '',
      amountPaise: row.amountPaise,
    }))
  }

  const applied: RedeemedCard[] = []
  let remaining = amountDuePaise

  for (const code of codes) {
    if (remaining <= 0) break

    // FOR UPDATE is the entire defence against double-spend. Read the row
    // under the lock; a value read before the lock is already stale.
    const locked = await tx.execute(sql`
      SELECT id, balance_paise, disabled_at, expires_at, code_last4
      FROM gift_card
      WHERE code_hash = ${hashGiftCardCode(code)}
      FOR UPDATE
    `)
    const row = locked.rows?.[0]

    // Same message for unknown, disabled and expired: distinguishing them
    // turns the endpoint into an oracle for which codes exist.
    if (!row) throw new GiftCardError('This gift card cannot be used')

    const card = {
      balancePaise: Number(row.balance_paise),
      disabledAt: row.disabled_at ? new Date(row.disabled_at) : null,
      expiresAt: row.expires_at ? new Date(row.expires_at) : null,
    }
    if (giftCardStatus(card as any) !== 'active') {
      throw new GiftCardError('This gift card cannot be used')
    }

    // Re-clamp against the live balance. The quote shown at code entry is
    // advisory and may be hours old.
    const amount = Math.min(card.balancePaise, remaining)
    if (amount <= 0) continue

    const balanceAfter = card.balancePaise - amount

    await tx.update(giftCards)
      .set({ balancePaise: balanceAfter, updatedAt: new Date() })
      .where(eq(giftCards.id, row.id))

    await tx.insert(giftCardTransactions).values({
      giftCardId: row.id,
      type: 'redeem',
      amountPaise: amount,
      balanceAfterPaise: balanceAfter,
      orderId,
      userId,
      description: `Redeemed towards order`,
    })

    await tx.insert(orderGiftCards).values({
      orderId,
      giftCardId: row.id,
      amountPaise: amount,
    })

    applied.push({ giftCardId: row.id, last4: row.code_last4, amountPaise: amount })
    remaining -= amount
  }

  return applied
}

/** Quote only — debits nothing. What the checkout screen calls. */
export async function quoteGiftCard(code: string, amountDuePaise: number) {
  const card = await db.query.giftCards.findFirst({
    where: eq(giftCards.codeHash, hashGiftCardCode(code)),
  })
  if (!card || giftCardStatus(card) !== 'active') {
    throw new GiftCardError('This gift card cannot be used')
  }
  return {
    giftCardId: card.id,
    last4: card.codeLast4,
    balancePaise: card.balancePaise,
    applicablePaise: Math.min(card.balancePaise, amountDuePaise),
  }
}

