/**
 * Releases balance held for an order that never completed.
 *
 * Payment initiation debits the card; if the customer walks away or the order
 * is cancelled, that money has to come back. Skipping this path loses
 * customer balance silently — it looks identical to a card that was spent.
 */
export async function voidGiftCardHold(tx: any, orderId: string): Promise<number> {
  const applications = await tx.select().from(orderGiftCards).where(eq(orderGiftCards.orderId, orderId))
  if (applications.length === 0) return 0

  let released = 0
  for (const application of applications) {
    const [card] = await tx.execute(sql`
      SELECT id, balance_paise FROM gift_card WHERE id = ${application.giftCardId} FOR UPDATE
    `).then((r: any) => r.rows)

    const balanceAfter = Number(card.balance_paise) + application.amountPaise
    await tx.update(giftCards)
      .set({ balancePaise: balanceAfter, updatedAt: new Date() })
      .where(eq(giftCards.id, application.giftCardId))

    await tx.insert(giftCardTransactions).values({
      giftCardId: application.giftCardId,
      type: 'void',
      amountPaise: application.amountPaise,
      balanceAfterPaise: balanceAfter,
      orderId,
      description: 'Hold released — order did not complete',
    })
    released += application.amountPaise
  }

  // Deleting the applications is what makes this idempotent: a second call
  // finds nothing to release.
  await tx.delete(orderGiftCards).where(eq(orderGiftCards.orderId, orderId))
  await tx.update(orders).set({ giftCardAmount: '0.00' }).where(eq(orders.id, orderId))

  return released
}

/**
 * Credits a refund back to the cards that paid for the order.
 *
 * `order_gift_card` is never mutated here — it is the permanent record of
 * what was applied, and the cap below is measured against it.
 */
export async function refundToGiftCards(
  tx: any,
  orderId: string,
  giftCardLegPaise: number,
): Promise<Array<{ giftCardId: string; amountPaise: number }>> {
  if (giftCardLegPaise <= 0) return []

  const applications = await tx.select().from(orderGiftCards)
    .where(eq(orderGiftCards.orderId, orderId))
    .orderBy(orderGiftCards.giftCardId) // stable order so the remainder lands predictably

  const totalApplied = applications.reduce((sum: number, a: any) => sum + a.amountPaise, 0)
  if (totalApplied === 0) return []

  const results = []
  let allocated = 0

  for (const [index, application] of applications.entries()) {
    const isLast = index === applications.length - 1
    // The last card absorbs the remainder so the parts sum to exactly the
    // leg. Rounding each share independently loses or invents paise.
    const share = isLast
      ? giftCardLegPaise - allocated
      : Math.round((giftCardLegPaise * application.amountPaise) / totalApplied)
    if (share <= 0) continue

    // Cap against what this card actually paid on THIS order. Two partial
    // refunds must not add up to more than the card contributed — that would
    // mint balance out of nothing.
    const [{ credited }] = await tx.execute(sql`
      SELECT COALESCE(SUM(amount_paise), 0)::int AS credited
      FROM gift_card_transaction
      WHERE gift_card_id = ${application.giftCardId}
        AND order_id = ${orderId}
        AND type = 'refund'
    `).then((r: any) => r.rows)

    if (credited + share > application.amountPaise) {
      throw new GiftCardError('Refund would exceed what this gift card paid on the order')
    }

    const [card] = await tx.execute(sql`
      SELECT id, balance_paise FROM gift_card WHERE id = ${application.giftCardId} FOR UPDATE
    `).then((r: any) => r.rows)

    const balanceAfter = Number(card.balance_paise) + share
    await tx.update(giftCards)
      .set({ balancePaise: balanceAfter, updatedAt: new Date() })
      .where(eq(giftCards.id, application.giftCardId))

    await tx.insert(giftCardTransactions).values({
      giftCardId: application.giftCardId,
      type: 'refund',
      amountPaise: share,
      balanceAfterPaise: balanceAfter,
      orderId,
      description: 'Refunded from order',
    })

    results.push({ giftCardId: application.giftCardId, amountPaise: share })
    allocated += share
  }

  return results
}

