/**
 * Mints and delivers scheduled gift cards.
 *
 * Minting happens HERE, not at payment time: the plaintext code is
 * returned once by issueGiftCard() and never stored (G5), so a card
 * created months before its send date could never be emailed.
 *
 * setInterval rather than BullMQ, matching services/approval-deadline.ts:251.
 * The repo already made that tradeoff; a second scheduling story costs
 * more than it buys.
 */
export async function sweepScheduledGiftCards(now = new Date()): Promise<number> {
  // Paid gift card orders whose send date has arrived and which have no
  // card yet. The LEFT JOIN is the cheap filter; the unique constraint
  // on purchase_order_id is the correctness guarantee.
  const due = await db.execute(sql`
    SELECT o.id, o.gift_card_purchase
    FROM orders o
    LEFT JOIN gift_card g ON g.purchase_order_id = o.id
    WHERE o.order_type = 'gift_card'
      AND o.payment_status = 'paid'
      AND g.id IS NULL
      AND (o.gift_card_purchase ->> 'sendAt')::timestamptz <= ${now}
    LIMIT 100
  `)

  let sent = 0
  for (const row of due.rows) {
    const purchase = row.gift_card_purchase as GiftCardPurchase

    try {
      // The unique constraint on purchase_order_id is what makes this
      // safe. Two workers racing, or a sweep racing a retried payment
      // verification, both reach this line; exactly one insert survives.
      // Reading "does a card exist yet" before writing would race in
      // precisely the window that matters.
      const { card, code } = await issueGiftCard({
        amountPaise: purchase.amountPaise,
        purchaseOrderId: row.id,
        recipientEmail: purchase.recipientEmail,
        recipientName: purchase.recipientName,
        senderName: purchase.senderName,
        message: purchase.message,
        sendAt: new Date(purchase.sendAt),
        description: 'Scheduled gift card delivered',
      })

      await sendGiftCardEmail(card, code)
      await db.update(giftCards)
        .set({ sentAt: new Date() })
        .where(eq(giftCards.id, card.id))
      sent++
    } catch (error) {
      const message = error instanceof Error ? error.message : String(error)
      // Lost the race to another worker. Nothing to do.
      if (message.includes('gift_card_purchase_order_id')) continue

      // Minted but unsent is recoverable from the admin screen, and one
      // bad address must not stall the batch. The code is never logged.
      logger.error({ orderId: row.id }, 'Gift card delivery failed')
    }
  }
  return sent
}

export function startGiftCardDeliveryScheduler(intervalMs = 5 * 60 * 1000) {
  return setInterval(() => {
    sweepScheduledGiftCards().catch((error) => {
      logger.error({ err: error }, 'Gift card delivery sweep failed')
    })
  }, intervalMs)
}

