/**
 * Which rung of the format axis a frame sits on.
 *
 * Unlike `frames.type`, which an admin invents freely, this set is closed: it
 * is the three groups the storefront's frame panel renders as
 * "Rolled Canvas/Frameless/Framed". FrameSelector used to derive the rung from
 * the type string, which put an admin-created FORMAT in the wrong group with
 * nothing to catch it. A column the admin picks turns that guess into data.
 */
export const frameCategoryEnum = pgEnum("frame_category", [
  "rolled",
  "frameless",
  "framed",
]);

// IN the frames table (:243):
//   type: frameTypeEnum("type").notNull(),
// BECOMES:

    /**
     * Slug identifying this moulding, e.g. `gold`, `stretch-maple`.
     *
     * Text rather than an enum because the admin creates frames: an enum is a
     * ceiling, and a Postgres enum cannot gain a value without a migration.
     * Unique because the storefront's swatch colour fallback is keyed on it,
     * so two frames sharing a type are indistinguishable to that lookup.
     */
    type: text("type").notNull(),

    category: frameCategoryEnum("category").notNull(),

// IN the table's index block, alongside typeIdx:
//   REPLACE  typeIdx: index("frames_type_idx").on(table.type),
//   WITH
    typeIdx: uniqueIndex("frames_type_idx").on(table.type),

// AT :328, the derived type export collapses — the storefront already treats
// frame type as a plain string (FrameSelector.tsx:409, stores/cart.ts:152):
//   DELETE  export type FrameType = (typeof frameTypeEnum.enumValues)[number];
//   ADD     export type FrameCategory = (typeof frameCategoryEnum.enumValues)[number];

// Import `uniqueIndex` from drizzle-orm/pg-core if it is not already imported.

-- Frames become admin-writable (#admin-frame-management).
--
-- Hand-written rather than generated: drizzle-kit emits no backfill, and every
-- statement below depends on the one before it.

--> statement-breakpoint
ALTER TABLE "frames" ADD COLUMN "category" text;
--> statement-breakpoint
-- Backfill BEFORE the NOT NULL, or the seven seeded rows fail the constraint.
-- rolled and frameless are formats and map to themselves; every other value in
-- the old enum is a moulding around a stretched canvas, so it folds into framed.
UPDATE frames SET category = CASE "type"::text
  WHEN 'rolled'    THEN 'rolled'
  WHEN 'frameless' THEN 'frameless'
  ELSE 'framed'
END;
--> statement-breakpoint
CREATE TYPE "public"."frame_category" AS ENUM('rolled', 'frameless', 'framed');
--> statement-breakpoint
ALTER TABLE "frames" ALTER COLUMN "category" SET DATA TYPE "public"."frame_category" USING "category"::"public"."frame_category";
--> statement-breakpoint
ALTER TABLE "frames" ALTER COLUMN "category" SET NOT NULL;
--> statement-breakpoint
ALTER TABLE "frames" ALTER COLUMN "type" SET DATA TYPE text;
--> statement-breakpoint
-- Only now: Postgres refuses to drop a type a column still references.
DROP TYPE "public"."frame_type";
--> statement-breakpoint
DROP INDEX IF EXISTS "frames_type_idx";
--> statement-breakpoint
CREATE UNIQUE INDEX "frames_type_idx" ON "frames" USING btree ("type");

-- Then append to migrations/meta/_journal.json:
--   { "idx": 14, "version": "7", "when": <epoch ms>, "tag": "0014_admin_editable_frames", "breakpoints": true }

// Add `category` to each of the seven rows in sampleFrames:
//   Rolled Canvas          -> category: "rolled"
//   Frameless              -> category: "frameless"
//   Stretch + Gold Frame   -> category: "framed"
//   Stretch + Silver Frame -> category: "framed"
//   Stretch + Black Frame  -> category: "framed"
//   Stretch + White Frame  -> category: "framed"
//   Stretch + Wood Frame   -> category: "framed"
