/**
 * Retire a frame.
 *
 * Archives; never deletes. `cartItems.frameId` and `orderItems.frameId` are
 * both `onDelete: "set null"`, so a hard delete would succeed quietly and take
 * the frame off historical orders with it — the same reason products archive
 * (admin/products.ts:642) rather than disappear.
 *
 * Refuses the last active frame. There is no "no frame" fallback on the buy
 * panel: Rolled Canvas is itself a row here, so zero active frames is a
 * product page with nothing to buy.
 */
adminFramesApp.delete("/:id", async (c) => {
  const { id } = c.req.param();

  const existing = await db
    .select({ id: frames.id, name: frames.name, isActive: frames.isActive })
    .from(frames)
    .where(eq(frames.id, id))
    .limit(1);

  if (existing.length === 0) {
    return c.json({ error: "Frame not found" }, 404);
  }

  if (existing[0].isActive) {
    const [{ count: activeCount }] = await db
      .select({ count: count() })
      .from(frames)
      .where(eq(frames.isActive, true));

    if (activeCount <= 1) {
      return c.json(
        {
          error:
            "Cannot archive the last active frame — the product page would have no format option to sell.",
        },
        409
      );
    }

    await db
      .update(frames)
      .set({ isActive: false, updatedAt: new Date() })
      .where(eq(frames.id, id));

    await purgeFramesCache();
  }

  return c.json({ message: `Frame '${existing[0].name}' archived` });
});

