// Export both the component and the validator, matching
// routes/admin/shipping.tsx — the test renders them without a router.
//
// validateFrame(input) runs updateFrameInputSchema and maps the ZodError onto
// per-field messages. It does NOT restate any bound. The schema is the single
// definition of what a frame may hold, and the API validates with the same one.
//
// The swatch field posts a single multipart file to
// POST /api/admin/frames/upload-image and stores BOTH urls off the response.
// No second image input: the variant ladder already carries a thumbnail and a
// card size, so a second field would be a second thing to keep in sync.
//
// The type input shows its constraint inline ("lowercase letters, digits and
// hyphens") rather than leaving the admin to discover it by rejection.
//
// `submitError` prop renders the API's message verbatim. A 409 arrives naming
// the slug that is taken; collapsing that into "something went wrong" throws
// away the only part the admin can act on.
//
// Leave a slot below the two price inputs for the preview — next ticket.

// new.tsx  — createFileRoute, empty FrameForm, POST /api/admin/frames on submit,
//            navigate back to the list on 201.
// $id.tsx  — createFileRoute, loads the frame, FrameForm seeded with it,
//            PATCH /api/admin/frames/:id on submit.
//
// Both surface the API's error message through the form's submitError prop.
// routeTree.gen.ts regenerates on the next dev/build run — do not hand-edit it.

/**
 * What the admin sees a frame cost while they type its price.
 *
 * The coupling case below is the reason this component exists in this shape.
 * #566 was a mispricing that survived because the PDP re-derived a formula the
 * server already owned, and every seeded frame happened to make the two agree
 * — priceAddition was 0.00 everywhere, so dropping it changed nothing until an
 * admin could set it. Which is exactly what this feature enables.
 *
 * So the preview does not compute anything. It calls frameAddition, and this
 * asserts it against frameAddition's own output for a frame carrying BOTH a
 * non-zero modifier and a non-zero addition — the case that had no coverage.
 */

import { describe, it, expect, afterEach } from 'vitest'
import { render, screen, cleanup } from '@testing-library/react'
import {
  frameAddition,
  FRAME_PREVIEW_REFERENCE_PRICES,
} from '@chobii/shared'
import {
  FramePricePreview,
  framePreviewRows,
} from '~/routes/admin/frames/FramePricePreview'

afterEach(cleanup)

const BOTH_NON_ZERO = { priceModifier: '1.40', priceAddition: '250.00' }

describe('framePreviewRows', () => {
  it('is the shared formula, not a copy of it — including the flat column', () => {
    const rows = framePreviewRows(BOTH_NON_ZERO)
    expect(rows).toHaveLength(FRAME_PREVIEW_REFERENCE_PRICES.length)
    rows.forEach((row, i) => {
      const price = FRAME_PREVIEW_REFERENCE_PRICES[i]
      expect(row.basePrice).toBe(price)
      expect(row.addition).toBe(frameAddition(price, BOTH_NON_ZERO))
      expect(row.total).toBe(price + frameAddition(price, BOTH_NON_ZERO))
    })
  })

  it('does not drop the flat addition — the #566 failure, from the admin side', () => {
    const withFlat = framePreviewRows(BOTH_NON_ZERO)
    const withoutFlat = framePreviewRows({
      priceModifier: '1.40',
      priceAddition: '0.00',
    })
    withFlat.forEach((row, i) => {
      expect(row.addition - withoutFlat[i].addition).toBe(250)
    })
  })

  it('quotes zero uplift for a frame that adds nothing', () => {
    const rows = framePreviewRows({ priceModifier: '1.00', priceAddition: '0.00' })
    rows.forEach((row) => expect(row.addition).toBe(0))
  })

  it('honours the clamp — a below-one modifier does not discount the piece', () => {
    const rows = framePreviewRows({ priceModifier: '0.80', priceAddition: '0.00' })
    rows.forEach((row) => expect(row.addition).toBe(0))
  })

  it('scales with the piece, which is why there is more than one row', () => {
    const rows = framePreviewRows({ priceModifier: '1.40', priceAddition: '0.00' })
    const additions = rows.map((r) => r.addition)
    expect(additions[1]).toBeGreaterThan(additions[0])
    expect(additions[2]).toBeGreaterThan(additions[1])
  })
})

describe('FramePricePreview', () => {
  it('renders a row per reference price', () => {
    render(<FramePricePreview pricing={BOTH_NON_ZERO} />)
    for (const price of FRAME_PREVIEW_REFERENCE_PRICES) {
      expect(
        screen.getByText(new RegExp(price.toLocaleString('en-IN')))
      ).toBeInTheDocument()
    }
  })

  it('renders nothing rather than NaN while the field is mid-edit', () => {
    render(<FramePricePreview pricing={{ priceModifier: '', priceAddition: '' }} />)
    expect(screen.queryByText(/NaN/)).toBeNull()
  })
})

import { frameAddition, FRAME_PREVIEW_REFERENCE_PRICES, type FramePriceColumns } from '@chobii/shared'

/**
 * What this frame would add, at three sizes of piece.
 *
 * The arithmetic is `frameAddition`'s and nothing here reproduces it. #566 was
 * a mispricing that lived for months because the product page re-derived a
 * formula the server already owned, and it stayed invisible because every
 * seeded frame had a zero flat column — so the two answers agreed by accident.
 * This screen is the one that lets an admin make that column non-zero. A
 * preview with its own arithmetic would be the same bug in the worst possible
 * place: the screen whose job is to convince the admin the number is right.
 *
 * Three reference prices rather than one because a frame is priced as a
 * proportion of the piece precisely so its cost tracks the size of it. One
 * sample row would show a number while hiding the behaviour being chosen.
 */
export function framePreviewRows(pricing: FramePriceColumns) {
  return FRAME_PREVIEW_REFERENCE_PRICES.map((basePrice) => {
    const addition = frameAddition(basePrice, pricing)
    return { basePrice, addition, total: basePrice + addition }
  })
}

export function FramePricePreview({ pricing }: { pricing: FramePriceColumns }) {
  // Render nothing while a field is mid-edit rather than quoting NaN at an
  // admin who is halfway through typing a number.
