import { describe, it, expect, afterEach } from 'vitest'
import { render, screen, cleanup, waitFor } from '@testing-library/react'
import userEvent from '@testing-library/user-event'
import { ConfirmProvider, useConfirm } from '~/components/admin/useConfirm'

afterEach(cleanup)

function Harness({ onResult }: { onResult: (v: boolean) => void }) {
  const confirmAction = useConfirm()
  return (
    <button onClick={async () => onResult(await confirmAction({ title: 'Cancel order?', body: 'Order A-1 will be cancelled.', confirmLabel: 'Cancel order', destructive: true }))}>
      trigger
    </button>
  )
}

const renderHarness = (onResult: (v: boolean) => void) =>
  render(<ConfirmProvider><Harness onResult={onResult} /></ConfirmProvider>)

describe('ConfirmDialog', () => {
  it('resolves true when the destructive action is confirmed', async () => {
    const results: boolean[] = []
    renderHarness((v) => results.push(v))
    await userEvent.click(screen.getByRole('button', { name: 'trigger' }))
    const dialog = await screen.findByRole('dialog')
    expect(dialog).toHaveAttribute('aria-modal', 'true')
    await userEvent.click(screen.getByRole('button', { name: 'Cancel order' }))
    await waitFor(() => expect(results).toEqual([true]))
  })

  it('resolves false on Escape and never leaves the dialog mounted', async () => {
    const results: boolean[] = []
    renderHarness((v) => results.push(v))
    const trigger = screen.getByRole('button', { name: 'trigger' })
    await userEvent.click(trigger)
    await screen.findByRole('dialog')
    await userEvent.keyboard('{Escape}')
    await waitFor(() => expect(results).toEqual([false]))
    expect(screen.queryByRole('dialog')).toBeNull()
    expect(document.activeElement).toBe(trigger)
  })
})

