import { drizzle } from 'drizzle-orm/postgres-js'
import postgres from 'postgres'
import * as schema from '../../src/database/schema'

export interface LiveDbHandle {
  client: ReturnType<typeof postgres> | undefined
  db: ReturnType<typeof drizzle<typeof schema>> | undefined
  reachable: boolean
}

/**
 * Connect, or report unreachable. Never throws: a suite that needs a real
 * database asserts that separately with assertLiveDbReachable, so a missing
 * database is a loud skip rather than eleven identical stack traces.
 */
export async function connectLiveDb(): Promise<LiveDbHandle> {
  const url = liveDbUrl()
  if (!url) return { client: undefined, db: undefined, reachable: false }

  try {
    const client = postgres(url, { max: 5, onnotice: () => {} })
    await client`SELECT 1`
    return { client, db: drizzle(client, { schema }), reachable: true }
  } catch {
    return { client: undefined, db: undefined, reachable: false }
  }
}

export async function closeLiveDb(handle: LiveDbHandle): Promise<void> {
  if (handle.client) await handle.client.end()
}

let counter = 0

/**
 * A gift-card code unique to this process and this call.
 *
 * The pid is in there because suites run in parallel workers against ONE
 * database and the code column is unique — two workers generating "TEST0001"
 * is a flake that only shows up under load.
 */
export function freshGiftCardCode(prefix: string): string {
  counter += 1
  return `${prefix}${String(process.pid).padStart(6, '0')}${String(counter).padStart(7, '0')}`.slice(0, 16)
}

